    if (audioRender_ == nullptr) {
        AUDIO_ERR_LOG("render is nullptr");
        ctrlState_.store(CtrlState::CTRL_STARTED); // legacy contract: started_ stays true on failure
        return ERR_INVALID_HANDLE;
    }
